// Validate and normalize an inbound lead payload.
// This file is embedded verbatim into the n8n "Validate & Normalize" Code node
// by scripts/build-workflow.mjs, and unit-tested with node:test.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const FREE_EMAIL_DOMAINS = [
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com',
  'aol.com', 'proton.me', 'protonmail.com', 'live.com', 'ymail.com',
];

const BUDGET_BANDS = {
  '<1k': 500,
  '1k-5k': 3000,
  '5k-15k': 10000,
  '15k-50k': 30000,
  '50k+': 75000,
};

function clean(value, max = 2000) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/\s+/g, ' ').trim().slice(0, max);
}

function parseBudget(raw) {
  const v = clean(raw).toLowerCase().replace(/[$,\s]/g, '');
  if (!v) return { band: 'unknown', estimate: 0 };
  if (BUDGET_BANDS[v] !== undefined) return { band: v, estimate: BUDGET_BANDS[v] };
  const num = Number(v.replace(/k$/, '000'));
  if (Number.isFinite(num) && num > 0) {
    let band = '<1k';
    if (num >= 50000) band = '50k+';
    else if (num >= 15000) band = '15k-50k';
    else if (num >= 5000) band = '5k-15k';
    else if (num >= 1000) band = '1k-5k';
    return { band, estimate: num };
  }
  return { band: 'unknown', estimate: 0 };
}

function validateLead(raw) {
  const body = raw && typeof raw === 'object' ? raw : {};
  const errors = [];

  const name = clean(body.name || body.full_name, 120);
  const email = clean(body.email, 200).toLowerCase();
  const company = clean(body.company, 160);
  const role = clean(body.role || body.job_title, 120);
  const website = clean(body.website, 200);
  const message = clean(body.message || body.notes, 3000);
  const source = clean(body.source || 'website', 60).toLowerCase();
  const timeline = clean(body.timeline, 60).toLowerCase();
  const companySize = clean(body.company_size, 30);
  const budget = parseBudget(body.budget);

  if (!name) errors.push('name is required');
  if (!email) errors.push('email is required');
  else if (!EMAIL_RE.test(email)) errors.push('email is invalid');
  if (!message || message.length < 10) errors.push('message must be at least 10 characters');

  // Honeypot field: real users never fill it in.
  if (clean(body.website_confirm)) errors.push('spam detected');

  const domain = email.includes('@') ? email.split('@')[1] : '';
  const lead = {
    lead_id: `L-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    received_at: new Date().toISOString(),
    name,
    email,
    email_domain: domain,
    is_business_email: Boolean(domain) && !FREE_EMAIL_DOMAINS.includes(domain),
    company,
    role,
    website,
    company_size: companySize,
    budget_band: budget.band,
    budget_estimate: budget.estimate,
    timeline: timeline || 'unknown',
    source,
    message,
  };

  return { valid: errors.length === 0, errors, lead };
}

if (typeof module !== 'undefined') {
  module.exports = { validateLead, parseBudget, clean, FREE_EMAIL_DOMAINS };
}

// ---- n8n entry point ----
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const result = validateLead(body);
  out.push({ json: result });
}
return out;

// Deterministic rule-based lead scoring.
// Used as (1) a fallback when the AI call fails or returns unusable output and
// (2) a sanity check that is stored next to the AI score for auditing.

const SENIOR_ROLE_RE = /\b(founder|co-?founder|ceo|cto|coo|cmo|owner|director|vp|vice president|head of|partner|president)\b/i;
const MID_ROLE_RE = /\b(manager|lead|principal|senior)\b/i;
const INTENT_RE = /\b(asap|urgent|this month|this quarter|ready to start|budget approved|looking to hire|need help|proposal|quote|pricing)\b/i;
const NEGATED_RE = /\b(not|no|isn't|is not|nothing)\s+(\w+\s+)?(urgent|asap|rush|ready|budget)\w*/gi;
const LOW_INTENT_RE =/\b(just curious|student|homework|free|no budget|internship|job application|seo backlinks|guest post)\b/i;

function sizeScore(size) {
  const s = String(size || '').replace(/\s/g, '');
  if (!s) return 0;
  if (/^(1|1-10|2-10)$/.test(s)) return 5;
  if (/^(11-50)$/.test(s)) return 12;
  if (/^(51-200)$/.test(s)) return 18;
  if (/^(201-1000|201-500|501-1000)$/.test(s)) return 20;
  if (/1000\+|1001/.test(s)) return 15; // big companies are slower to buy from freelancers
  return 5;
}

function budgetScore(band) {
  return { '<1k': 2, '1k-5k': 12, '5k-15k': 22, '15k-50k': 28, '50k+': 30 }[band] || 0;
}

function timelineScore(timeline) {
  const t = String(timeline || '').toLowerCase();
  if (/asap|immediately|this week|<1 ?month|1 month|this month/.test(t)) return 15;
  if (/1-3|quarter|next month|2 months|3 months/.test(t)) return 10;
  if (/3-6|6 months|later|exploring/.test(t)) return 4;
  return 0;
}

function tierFor(score) {
  if (score >= 70) return 'hot';
  if (score >= 40) return 'warm';
  return 'cold';
}

function ruleBasedScore(lead) {
  const reasons = [];
  let score = 0;

  const b = budgetScore(lead.budget_band);
  score += b;
  if (b) reasons.push(`budget ${lead.budget_band} (+${b})`);

  const t = timelineScore(lead.timeline);
  score += t;
  if (t) reasons.push(`timeline ${lead.timeline} (+${t})`);

  const s = sizeScore(lead.company_size);
  score += s;
  if (s) reasons.push(`company size ${lead.company_size} (+${s})`);

  if (SENIOR_ROLE_RE.test(lead.role || '')) {
    score += 15;
    reasons.push('decision-maker role (+15)');
  } else if (MID_ROLE_RE.test(lead.role || '')) {
    score += 8;
    reasons.push('manager-level role (+8)');
  }

  if (lead.is_business_email) {
    score += 10;
    reasons.push('business email domain (+10)');
  }

  // Remove negated phrases ("not urgent", "no rush") before checking intent.
  const intentText = String(lead.message || '').replace(NEGATED_RE, ' ');
  if (INTENT_RE.test(intentText)) {
    score += 10;
    reasons.push('buying-intent language (+10)');
  }

  if (LOW_INTENT_RE.test(lead.message || '')) {
    score -= 25;
    reasons.push('low-intent or off-topic language (-25)');
  }

  score = Math.max(0, Math.min(100, score));
  return { score, tier: tierFor(score), reasons };
}

if (typeof module !== 'undefined') {
  module.exports = { ruleBasedScore, tierFor, budgetScore, timelineScore, sizeScore };
}

// Parse and validate the LLM's qualification output.
// LLMs occasionally wrap JSON in prose or code fences, truncate it, or return
// out-of-range values. This module repairs what it safely can and falls back to
// the rule-based score otherwise, so the workflow never breaks on bad output.

const VALID_TIERS = ['hot', 'warm', 'cold'];
const VALID_SERVICES = [
  'ai_automation', 'dashboard', 'data_analytics', 'market_research',
  'web_app', 'ai_integration', 'other',
];

function extractJson(text) {
  if (!text || typeof text !== 'string') return null;
  let t = text.trim();
  // Strip markdown code fences.
  t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  const start = t.indexOf('{');
  if (start === -1) return null;
  let candidate = t.slice(start);
  const end = candidate.lastIndexOf('}');
  if (end !== -1) {
    try {
      return JSON.parse(candidate.slice(0, end + 1));
    } catch (e) {
      // fall through to repair
    }
  }
  // Repair: close an unterminated string and balance braces/brackets.
  const quoteCount = (candidate.match(/(?<!\\)"/g) || []).length;
  if (quoteCount % 2 === 1) candidate += '"';
  candidate = candidate.replace(/,\s*$/, '');
  const opens = (candidate.match(/\{/g) || []).length;
  const closes = (candidate.match(/\}/g) || []).length;
  const openArr = (candidate.match(/\[/g) || []).length;
  const closeArr = (candidate.match(/\]/g) || []).length;
  candidate += ']'.repeat(Math.max(0, openArr - closeArr));
  candidate += '}'.repeat(Math.max(0, opens - closes));
  try {
    return JSON.parse(candidate);
  } catch (e) {
    return null;
  }
}

function parseAiResponse(text, fallback) {
  const parsed = extractJson(text);
  const issues = [];

  if (!parsed || typeof parsed !== 'object') {
    return {
      ...fallback,
      source: 'rules_fallback',
      summary: 'AI output could not be parsed; rule-based score used.',
      service: 'other',
      next_action: 'Review manually',
      reply_draft: '',
      issues: ['unparseable_ai_output'],
    };
  }

  let score = Number(parsed.score);
  if (!Number.isFinite(score)) {
    issues.push('missing_score');
    score = fallback.score;
  }
  score = Math.round(Math.max(0, Math.min(100, score)));

  let tier = String(parsed.tier || '').toLowerCase();
  if (!VALID_TIERS.includes(tier)) {
    issues.push('invalid_tier');
    tier = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';
  }

  let service = String(parsed.service || 'other').toLowerCase();
  if (!VALID_SERVICES.includes(service)) {
    issues.push('invalid_service');
    service = 'other';
  }

  // Flag large disagreement between AI and rules for human review.
  const disagreement = Math.abs(score - fallback.score);
  if (disagreement >= 40) issues.push(`ai_rules_disagreement_${disagreement}`);

  return {
    score,
    tier,
    service,
    summary: String(parsed.summary || '').slice(0, 500),
    next_action: String(parsed.next_action || '').slice(0, 200),
    reply_draft: String(parsed.reply_draft || '').slice(0, 2000),
    reasons: Array.isArray(parsed.reasons) ? parsed.reasons.slice(0, 6).map(String) : [],
    rules_score: fallback.score,
    source: 'ai',
    issues,
  };
}

if (typeof module !== 'undefined') {
  module.exports = { extractJson, parseAiResponse, VALID_SERVICES };
}

// ---- n8n entry point ----
const lead = $('Validate & Normalize').first().json.lead;
const rules = ruleBasedScore(lead);
const response = $input.first().json;
let text = '';
if (response && Array.isArray(response.content)) {
  text = response.content.filter((c) => c.type === 'text').map((c) => c.text).join('');
}
if (response && response.error) {
  text = '';
}
const result = parseAiResponse(text, rules);
return [{
  json: {
    ...lead,
    score: result.score,
    tier: result.tier,
    service: result.service,
    summary: result.summary,
    next_action: result.next_action,
    reply_draft: result.reply_draft,
    reasons: (result.reasons && result.reasons.length ? result.reasons : rules.reasons).join('; '),
    rules_score: rules.score,
    scoring_source: result.source,
    issues: (result.issues || []).join(', '),
    needs_review: (result.issues || []).length > 0,
  },
}];

